// ============================================================================
// SEED FUNCTION — idempotente, roda em todo boot
// ============================================================================
export async function seedOfficialClasses(): Promise<{ inserted: number; skipped: number }> {
  const db = await getDb();
  if (!db) {
    console.warn("[Seed] Banco não disponível, pulando seed de classes oficiais.");
    return { inserted: 0, skipped: 0 };
  }

  const ALL_CLASSES = [...COR_CLASSES, ...PORTE_CLASSES];
  let inserted = 0;
  let skipped = 0;

  for (const cls of ALL_CLASSES) {
    try {
      const interpretedTraits = interpretOfficialClass(cls.officialName);
      const result = await db
        .insert(official_bird_classes)
        .values({
          officialCode: cls.officialCode,
          officialName: cls.officialName,
          abbreviation: cls.abbreviation,
          modality: cls.modality,
          groupName: cls.groupName,
          subgroupName: cls.subgroupName,
          breedName: cls.breedName,
          bitola: cls.bitola,
          categoryName: cls.categoryName,
          sourceYear: 2026,
          sourceEntity: "FOB/OBJO",
          interpretedTraits: interpretedTraits as Record<string, unknown> | null,
          active: true,
        })
        .onConflictDoNothing()
        .returning({ id: official_bird_classes.id });

      if (result.length > 0) {
        inserted++;
      } else {
        skipped++;
      }
    } catch (error) {
      console.error(`[Seed] Erro ao inserir ${cls.officialCode}:`, error);
      skipped++;
    }
  }

  console.log(
    `[Seed] Classes oficiais FOB/OBJO 2026: ${inserted} inseridas, ${skipped} já existiam. Total: ${ALL_CLASSES.length}`
  );
  return { inserted, skipped };
}
